// Pure offer matching. Mapping data is generated by truck_fit.py, never guessed here.
(function(root,factory){const api=factory();root.TruckFit=api;if(typeof module==='object'&&module.exports)module.exports=api;})(typeof globalThis!=='undefined'?globalThis:this,function(){
 'use strict';
 const bands=['7.75','8.0','8.25','8.5','8.75','9.0','9.5+'];
 const brands={independent:'Independent',ace:'Ace',venture:'Venture',thunder:'Thunder',krux:'Krux',royal:'Royal',tensor:'Tensor',slappy:'Slappy'};
 function fits(values){return bands.filter(v=>(values||[]).map(String).includes(v));}
 function natives(values){return [...new Set((values||[]).map(String).filter(v=>/^[a-z]+:(?:\d{2,3}|\d{1,2}\.\d+)$/.test(v)))].sort();}
 function offers(row){const data=row.dataset||row;try{return Array.isArray(data.truckOffers)?data.truckOffers:JSON.parse(data.truckOffers||'[]');}catch(_){return [];}}
 function options(row,picked={},ranges={}){return offers(row).filter(o=>{
  if(o.available===false)return false;
  if(picked.fits?.length&&!picked.fits.some(value=>(o.fits||[]).includes(value)))return false;
  if(picked.native?.length&&!picked.native.includes(o.key))return false;
  const price=Number(o.price),compare=Number(o.compare);if(o.price==null||!Number.isFinite(price)||price<=0)return false;
  const discount=o.compare!=null&&compare>0?(compare-price)/compare*100:null;
  return (ranges.priceMin==null||price>=ranges.priceMin)&&(ranges.priceMax==null||price<=ranges.priceMax)&&
   (ranges.discountMin==null||(discount!=null&&discount>=ranges.discountMin))&&(ranges.discountMax==null||(discount!=null&&discount<=ranges.discountMax));
 });}
 function cheapest(row,picked,ranges){const values=options(row,picked,ranges);if(!values.length)return null;return {...values.reduce((a,b)=>Number(a.price)<=Number(b.price)?a:b),truck:true};}
 function range(o){const r=o.ideal||o.maximum||o.guidance;if(!r)return 'fit not verified';return (o.ideal?'fits ':o.maximum?'maximum range ':'owner guidance ')+(r[1]==null?r[0]+'+':r[0]+'–'+r[1])+'″';}
 function label(o){return (brands[o.brand]||o.brand_label||'')+' '+(o.native||'size not listed')+' · '+range(o)+(o.conflict?' · conflicting inch size':'');}
 function nativeLabel(key){const [brand,code]=key.split(':');return (brands[brand]||brand)+' '+code;}
 function paintCompare(node,offer){
  if(node.dataset.truckOriginal===undefined)node.dataset.truckOriginal=node.dataset.original||'';
  node.dataset.original=offer?.truck?(offer.compare==null?'':String(offer.compare)):node.dataset.truckOriginal;
  node.querySelectorAll('.avg-price').forEach(n=>{
   if(n.dataset.truckBaseText===undefined){n.dataset.truckBaseText=n.textContent;n.dataset.truckBaseHidden=String(n.hidden);}
   if(!offer?.truck){n.textContent=n.dataset.truckBaseText;n.hidden=n.dataset.truckBaseHidden==='true';return;}
   n.hidden=offer.compare==null;n.textContent=offer.compare==null?'':'Was '+(n.dataset.truckBaseText.includes('€')?'€':'$')+Number(offer.compare).toFixed(2);
  });
 }
 return {bands,brands,fits,natives,offers,options,cheapest,range,label,nativeLabel,paintCompare};
});
